specimens.css:
/* 状态模拟：.detailsResize 的 :hover、:active、:focus-visible 都是同一条
   background: var(--dsw-alias-state-business-primary)，静态快照无法真的悬停这条 5px 高的分隔条。 */
.detailsResize { background: var(--dsw-alias-state-business-primary); }

/* 状态模拟：浮层是 portal 到 body 的 position: fixed 面板，快照里拉回文档流；
   保留 relative 让菜单材质层（material，inset: 0）仍以卡片为包含块。 */
.typeFilterPanel { position: relative; inset: auto; }

/* 状态模拟：类型筛选浮层在真实产品里 portal 到 body、由 useAnchoredPosition 定位成 fixed。
   快照里写回 relative + inset:auto，让菜单材质层（material，inset: 0）仍以卡片为包含块。 */
.typeFilterPanel { position: relative; inset: auto; }

/* 状态模拟：.resize 的 :hover 与 :focus-visible 共用一条
   background: var(--dsw-alias-interactive-bg-hover)，静态快照无法真的悬停或聚焦它。 */
.resize { background: var(--dsw-alias-interactive-bg-hover); }
